// ---- ковры ----
const rugPat={
 'медальон':(c,S,W,H,col,rnd)=>{c.fillStyle=col[1];c.fillRect(0,0,W,H);c.strokeStyle=col[3];c.lineWidth=S*.05;c.strokeRect(S*.12,S*.12,W-S*.24,H-S*.24);c.lineWidth=S*.02;c.strokeRect(S*.22,S*.22,W-S*.44,H-S*.44);ell(c,W/2,H/2,W*.22,H*.22);c.fillStyle=col[3];c.fill();ell(c,W/2,H/2,W*.14,H*.14);c.fillStyle=col[0];c.fill();[[.25,.25],[.75,.25],[.25,.75],[.75,.75]].forEach(q=>{poly(c,[[W*q[0],H*q[1]-S*.1],[W*q[0]+S*.1,H*q[1]],[W*q[0],H*q[1]+S*.1],[W*q[0]-S*.1,H*q[1]]]);c.fillStyle=col[2];c.fill()})},
 'полосы':(c,S,W,H,col)=>{for(let i=0;i<W/(S*.18)+1;i++){c.fillStyle=[col[1],col[3],col[0],'#c6b28a'][i%4];c.fillRect(i*S*.18,0,S*.18,H)}},
 'ромбы':(c,S,W,H,col)=>{c.fillStyle=col[1];c.fillRect(0,0,W,H);const k=S*.35;for(let x=0;x<W+k;x+=k)for(let y=0;y<H+k;y+=k){poly(c,[[x,y-k/2.5],[x+k/2.5,y],[x,y+k/2.5],[x-k/2.5,y]]);c.fillStyle=(x/k+y/k)%2<1?col[3]:col[0];c.fill()}c.strokeStyle='#e0d0a0';c.lineWidth=S*.04;c.strokeRect(S*.06,S*.06,W-S*.12,H-S*.12)},
 'шашки':(c,S,W,H,col)=>{const k=S*.25;for(let x=0;x<W;x+=k)for(let y=0;y<H;y+=k){c.fillStyle=((x+y)/k)%2<1?col[2]:'#d8ccaa';c.fillRect(x,y,k,k)}},
 'узор-кайма':(c,S,W,H,col,rnd)=>{c.fillStyle=col[2];c.fillRect(0,0,W,H);c.fillStyle=col[0];c.fillRect(0,0,W,S*.18);c.fillRect(0,H-S*.18,W,S*.18);c.fillRect(0,0,S*.18,H);c.fillRect(W-S*.18,0,S*.18,H);c.fillStyle='#d8b860';for(let x=S*.1;x<W;x+=S*.2){circ(c,x,S*.09,S*.04);c.fill();circ(c,x,H-S*.09,S*.04);c.fill()}c.strokeStyle=col[0];c.lineWidth=S*.03;for(let i=0;i<4;i++){c.beginPath();c.moveTo(S*.3,S*.3+i*(H-S*.6)/3);c.bezierCurveTo(W*.4,rnd()*H,W*.6,rnd()*H,W-S*.3,S*.3+i*(H-S*.6)/3);c.stroke()}},
};
const rugShape={'прямоуг.':[2,3],'дорожка':[1,4],'малый':[2,2],'широкий':[3,4]};
const RUGC={'красный':P.red,'синий':P.blue,'зелёный':P.green,'пурпурный':P.purple};
let ci=0;for(const pt in rugPat)for(const sh in rugShape){const [w,h]=rugShape[sh];const cn=Object.keys(RUGC)[ci++%4];M.add({id:'md1-rug-'+slug(pt)+'-'+slug(sh),n:'Ковёр '+sh+' «'+pt+'»',cat:'Ковры',th:['таверна','замок','дом','дворец'],w,h,solid:false,layer:'floor',v:['col:красный|синий|зелёный|пурпурный'],draw:(c,S,p,rnd)=>{const col=RUGC[p.col]||RUGC[cn],W=w*S,H=h*S;c.save();c.translate(S*.05,S*.15);const ww=W-S*.1,hh=H-S*.3;rr(c,0,0,ww,hh,S*.03);c.clip();rugPat[pt](c,S,ww,hh,col,rnd);c.fillStyle='rgba(0,0,0,.08)';for(let i=0;i<40;i++){c.fillRect(rnd()*ww,rnd()*hh,S*.04,S*.01)}c.restore();ink(c,S,.02);c.strokeRect(S*.05,S*.15,W-S*.1,H-S*.3);c.strokeStyle='#c6b28a';c.lineWidth=S*.012;for(let x=S*.08;x<W-S*.05;x+=S*.05){c.beginPath();c.moveTo(x,S*.15);c.lineTo(x,S*.05);c.moveTo(x,H-S*.15);c.lineTo(x,H-S*.05);c.stroke()}}})}
const roundRug=(id,n,col,pat)=>M.add({id:'md1-'+id,n,cat:'Ковры',th:['дом','эльфы','храм'],w:2,h:2,solid:false,layer:'floor',draw:(c,S,p,rnd)=>{c.save();circ(c,S,S,S*.92);c.clip();c.fillStyle=col[1];c.fillRect(0,0,2*S,2*S);for(let i=6;i>0;i--){circ(c,S,S,S*.15*i);c.strokeStyle=i%2?col[3]:col[0];c.lineWidth=S*.06;c.stroke()}if(pat){for(let i=0;i<8;i++){const a=i/8*PI*2;c.fillStyle='#d8b860';ell(c,S+Math.cos(a)*S*.5,S+Math.sin(a)*S*.5,S*.12,S*.05,a);c.fill()}}c.restore();ink(c,S,.02);circ(c,S,S,S*.92);c.stroke()}});
roundRug('rug-round-red','Круглый ковёр (красный)',P.red,1);roundRug('rug-round-braided','Плетёный круглый половик',P.cloth,0);roundRug('rug-round-blue','Круглый ковёр с листьями (синий)',P.blue,1);
const pelt=(id,n,col,stripes,head)=>M.add({id:'md1-'+id,n,cat:'Ковры',th:['замок','охотничий домик','лагерь','север'],w:2,h:2,solid:false,layer:'floor',draw:(c,S,p,rnd)=>{const pts=[[1,.25],[1.35,.45],[1.85,.3],[1.65,.75],[1.6,1.3],[1.85,1.75],[1.3,1.55],[1,1.85],[.7,1.55],[.15,1.75],[.4,1.3],[.35,.75],[.15,.3],[.65,.45]].map(q=>[q[0]*S,q[1]*S]);poly(c,pts);c.fillStyle=lg(c,0,0,2*S,2*S,[col[2],col[0]]);c.fill();c.save();poly(c,pts);c.clip();c.strokeStyle='rgba(0,0,0,.25)';c.lineWidth=S*.012;for(let i=0;i<200;i++){const x=rnd()*2*S,y=rnd()*2*S;c.beginPath();c.moveTo(x,y);c.lineTo(x+S*.04,y+S*.06);c.stroke()}if(stripes){c.fillStyle='#1a1410';for(let i=0;i<8;i++){c.save();c.translate(S,S*(.5+i*.15));c.beginPath();c.ellipse(-S*.4,0,S*.2,S*.03,.3,0,PI*2);c.ellipse(S*.4,0,S*.2,S*.03,-.3,0,PI*2);c.fill();c.restore()}}c.restore();ink(c,S,.02);poly(c,pts);c.stroke();if(head){ell(c,S,S*.25,S*.2,S*.17);c.fillStyle=col[1];c.fill();ink(c,S,.02);c.stroke();c.fillStyle='#e8e0c8';circ(c,S*.92,S*.15,S*.02);c.fill();circ(c,S*1.08,S*.15,S*.02);c.fill()}}});
